window.AUTH=window.AUTH||{};window.AUTH["23-980"]={"d":"23-980","id":"2024/23-980","n":"Facebook v. Amalgamated Bank","briefs":[{"k":"petitioner","label":"Brief of petitioners Facebook, Inc., et al.","date":"2024-08-09","url":"https://www.supremecourt.gov/DocketPDF/23/23-980/322124/20240809133545974_23-980_petbrief.pdf","side":"pet","n":26},{"k":"respondent","label":"Brief of respondents Amalgamated Bank, et al.","date":"2024-09-24","url":"https://www.supremecourt.gov/DocketPDF/23/23-980/326742/20240924123045815_23-980%20Resp%20Brief.pdf","side":"res","n":63},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2024-10-01","url":"https://www.supremecourt.gov/DocketPDF/23/23-980/327326/20241001173556738_23-980bsacUS_FacebookvAmalgamatedBank.pdf","side":"us","n":41},{"k":"reply","label":"Reply of petitioners Facebook, Inc., et al.","date":"2024-10-24","url":"https://www.supremecourt.gov/DocketPDF/23/23-980/330176/20241024122050139_23-980_petreplybrief.pdf","side":"pet","n":22}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/604us1r02_j4ek.pdf","tr":true,"items":[{"t":"case","label":"Basic, Inc. v. Levinson","cite":"485 U.S. 224","y":1988,"id":"1987/86-279","sc":1,"by":{"0":"34","1":"15, 34, 35, 39, 40, 45, 46, 48","2":"15, 22, 23, 28","3":"14, 16"},"q":[{"src":"brief","b":0,"text":"certain information concerning corporate developments could well be of dubious significance.","cite":"485 U.S. 224, 231"},{"src":"brief","b":1,"text":"substantial likelihood that the disclosure of the omitted fact would have been viewed by the reasonable investor as having significantly altered the ‘total mix’ of information made available.","cite":"485 U.S. 224, 231-32"},{"src":"brief","b":1,"text":"tak[ing] care ‘not to set too low a standard of materiality.’","cite":"485 U.S. at 231"},{"src":"argument","who":"Mr. Russell","text":"Well, I don't think that a company is entitled to mislead people about something that occurred in the past that, under Basic, would be a material event just because it has an assessment that it's not going to happen again."}]},{"t":"case","label":"Bondali v. Yum! Brands, Inc.","cite":"620 Fed. Appx. 483","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./620/483/","by":{"0":"22, 40","2":"19, 20, 26","3":"3"},"q":[{"src":"brief","b":0,"text":"educate investors on what harms are currently affecting the company.","cite":"620 Fed. Appx. 483, 491"},{"src":"brief","b":0,"text":"anything regarding the current state of a corporation’s compliance, safety, or other operations from a statement intended to educate the investor on future harms.","cite":"620 Fed. Appx. at 491"}]},{"t":"case","label":"Corner Post, Inc. v. Board of Governors of Federal Reserve System","cite":"144 S. Ct. 2440","y":2024,"id":"2023/22-1008","sc":1,"by":{"0":"23"}},{"t":"case","label":"Denny v. Barber","cite":"576 F.2d 465","y":1978,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/576/465/","by":{"0":"36"}},{"t":"case","label":"Goldman Sachs Group, Inc. v. Arkansas Teacher Retirement System","cite":"594 U.S. 113","y":2021,"id":"2020/20-222","sc":1,"by":{"0":"33"}},{"t":"case","label":"Halliburton Co. v. Erica P. John Fund, Inc.","cite":"573 U.S. 258","y":2014,"id":"2013/13-317","sc":1,"by":{"0":"5","1":"38, 41"},"q":[{"src":"brief","b":1,"text":"These concerns are more appropriately addressed to Congress.","cite":"573 U.S. 258, 277"}]},{"t":"case","label":"Indiana Public Retirement System v. Pluralsight, Inc.","cite":"45 F.4th 1236","y":2022,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/45/1236/","by":{"0":"39","1":"14, 41, 42, 44"},"q":[{"src":"brief","b":0,"text":"virtually certain to result in the warned of harm to [the company’s] business.","cite":"45 F.4th 1236, 1256"},{"src":"brief","b":1,"text":"the risk had materialized or was virtually certain to occur.","cite":"45 F.4th at 1255"},{"src":"argument","who":"Mr. Barber","text":"There's one case from the Tenth Circuit that if you look at the end of the relevant section of the court's opinion, the Indiana Public Retirement case, the court does seem to apply it that way, and we think that's wrong."}]},{"t":"case","label":"Karth v. Keryx Biopharmaceuticals, Inc.","cite":"6 F.4th 123","y":2021,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.4th/6/123/","by":{"0":"39","1":"14, 42, 44","2":"17","3":"8"},"q":[{"src":"brief","b":0,"text":"virtually certain to result in the warned of harm to [the company’s] business.","cite":"6 F.4th 123, 139"}]},{"t":"case","label":"Kolominsky v. Root, Inc.","cite":"100 F.4th 675","y":2024,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/100/675/","by":{"0":"6, 38","3":"3"},"q":[{"src":"brief","b":0,"text":"shields companies * * * from liability when they make statements that are forward-looking and accompanied by meaningful cautionary language.","cite":"100 F.4th 675, 688-689"}]},{"t":"case","label":"Macquarie Infrastructure Corp. v. Moab Partners, L.P.","cite":"601 U.S. 257","y":2024,"id":"2023/22-1165","sc":1,"by":{"0":"5-6, 20, 31, 37","1":"13, 14, 19, 21, 36, 39, 42","2":"2, 13, 21, 24","3":"2, 14, 15"},"q":[{"src":"brief","b":0,"text":"do not create an affirmative duty to disclose any and all material information.","cite":"601 U.S. 257, 264"},{"src":"brief","b":0,"text":"[Section] 10(b) and Rule 10b-5(b) do not create an affirmative duty to disclose any and all material information.","cite":"601 U.S. at 264"},{"src":"brief","b":2,"text":"representations that state the truth only so far as it goes, while omitting critical qualifying information.","cite":"601 U.S. 257, 263"},{"src":"brief","b":3,"text":"create an affirmative duty to disclose any and all material information.","cite":"601 U.S. 257, 264-265"},{"src":"brief","b":3,"text":"do[es] not create an affirmative duty to disclose any and all material information.","cite":"601 U.S. at 264"},{"src":"argument","who":"Mr. Shanmugam","text":"And I do think that this Court can write an opinion that sort of draws a square around Item 105 disclosures because, while those are intended to be forward-looking, to warn about types of risks, you have Item 101, which requires a description of the business, you have Item 106, which is a very specific and recent item included in Regulation S-K to warn about cybersecurity events, and you also have Item 303, which this Court is well familiar with from the Macquarie case last spring, which is the Management Discussion & Analysis section, which requires broad disclosures about known trends and uncertainties."},{"src":"argument","who":"Mr. Shanmugam","text":"And yet, it is a fundamental principle that this Court has articulated in cases like Matrixx and Macquarie that that is not enough at least for 10(b) liability, where there cannot be pure omissions liability."}]},{"t":"case","label":"Matrixx Initiatives, Inc. v. Siracusano","cite":"563 U.S. 27","y":2011,"id":"2010/09-1156","sc":1,"by":{"0":"5, 20, 25","1":"13, 15, 35, 36, 47","2":"15, 22, 26, 28","3":"14"},"q":[{"src":"brief","b":0,"text":"companies can control what they have to disclose under [those provisions] by controlling what they say to the market.","cite":"563 U.S. 27, 45"},{"src":"brief","b":0,"text":"[e]ven with respect to information that a reasonable investor might consider material.","cite":"563 U.S. 27, 45"},{"src":"brief","b":1,"text":"‘allo[w] the court to draw the reasonable inference that the defendant is liable for the misconduct alleged.’","cite":"563 U.S. at 46"},{"src":"brief","b":2,"text":"a statistically significant number of adverse events","cite":"563 U.S. 27, 30"},{"src":"brief","b":2,"text":"a material misrepresentation or omission by the defendant.","cite":"563 U.S. at 37"},{"src":"brief","b":3,"text":"Even with respect to information that a reasonable investor might consider material,","cite":"563 U.S. 27, 45"}]},{"t":"case","label":"Merck Sharp & Dohme Corp. v. Albrecht","cite":"587 U.S. 299","y":2019,"id":"2018/17-290","sc":1,"by":{"0":"25"}},{"t":"case","label":"Omnicare, Inc. v. Laborers District Council Construction Industries Pension Fund","cite":"575 U.S. 175","y":2015,"id":"2014/13-435","sc":1,"by":{"0":"5, 20-22, 24-25","1":"23, 24, 35, 38","2":"2, 11, 13, 21, 22, 25, 26","3":"5"},"q":[{"src":"brief","b":0,"text":"the perspective of a reasonable investor.","cite":"575 U.S. 175, 186187"},{"src":"brief","b":0,"text":"depends on the perspective of a reasonable investor.","cite":"575 U.S. 175, 186-187"},{"src":"brief","b":2,"text":"may offer securities to the public only after filing a registration statement,","cite":"575 U.S. 175, 178"},{"src":"brief","b":2,"text":"depends on the perspective of a reasonable investor","cite":"575 U.S. 175, 186-187"},{"src":"argument","who":"Mr. Shanmugam","text":"Instead, the Court should adopt a similar approach to the one it took for statements of opinion in Omnicare. There, the Court held that statements of opinion were ordinarily not actionable as false statements, but the Court recognized that a statement of opinion could be misleading based on an embedded representation about how the speaker formed the opinion."},{"src":"argument","who":"Mr. Shanmugam","text":"This Court has made clear, most recently in Omnicare, that when you apply the reasonable investor standard, you assume that the reasonable investor is aware of the context, the regulatory framework, and so forth."},{"src":"argument","who":"Mr. Shanmugam","text":"The wording of the statement really matters because, after all, as the Court indicated in the opinion in Omnicare, when you're engaged in this analysis, you are looking closely, if necessary, at both the language of the statement and the context."}]},{"t":"case","label":"Rombach v. Chang","cite":"355 F.3d 164","y":2004,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/355/164/","by":{"0":"38","1":"14","2":"17"}},{"t":"case","label":"Set Capital LLC v. Credit Suisse Group AG","cite":"996 F.3d 64","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/996/64/","by":{"0":"39","1":"14, 44, 45"}},{"t":"case","label":"Tellabs, Inc. v. Makor Issues & Rights, Ltd.","cite":"551 U.S. 308","y":2007,"id":"2006/06-484","sc":1,"by":{"0":"35, 37","1":"41"}},{"t":"law","label":"Pub. L. No. 104-67","url":"https://www.govinfo.gov/link/plaw/104/public/67","by":{"0":"29, 38","1":"37","2":"24"}},{"t":"usc","label":"15 U.S.C. § 78a","url":"https://www.law.cornell.edu/uscode/text/15/78a","stext":{"head":"§78a. Short title","paras":[[0,"This chapter may be cited as the \"Securities Exchange Act of 1934.\""]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78a?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2-5, 9, 14-15, 19-20, 31, 34, 36, 42","2":"2"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"reg","label":"67 Fed. Reg. 58,480","url":"https://www.govinfo.gov/link/fr/67/58480","by":{"0":"6"}},{"t":"reg","label":"70 Fed. Reg. 44,830","url":"https://www.govinfo.gov/link/fr/70/44830","by":{"0":"7"}},{"t":"reg","label":"81 Fed. Reg. 23,956","url":"https://www.govinfo.gov/link/fr/81/23956","by":{"0":"32"}},{"t":"reg","label":"84 Fed. Reg. 12,688","url":"https://www.govinfo.gov/link/fr/84/12688","by":{"0":"6, 7"}},{"t":"reg","label":"84 Fed. Reg. 44,375","url":"https://www.govinfo.gov/link/fr/84/44375","by":{"0":"32"}},{"t":"reg","label":"85 Fed. Reg. 63,743","url":"https://www.govinfo.gov/link/fr/85/63743","by":{"0":"32, 33"}},{"t":"reg","label":"88 Fed. Reg. 51,896","url":"https://www.govinfo.gov/link/fr/88/51896","by":{"0":"23","1":"32","2":"18"}},{"t":"case","label":"Amgen Inc. v. Conn. Ret. Plans & Tr. Funds","cite":"568 U.S. 455","y":2013,"id":"2012/11-1085","sc":1,"by":{"1":"41"}},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"by":{"1":"36"}},{"t":"case","label":"Bell Atlantic Corp. v. Twombly","cite":"550 U.S. 544","y":2007,"id":"2006/05-1126","sc":1,"by":{"1":"36"}},{"t":"case","label":"Berson v. Applied Signal Tech., Inc.","cite":"527 F.3d 982","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/527/982/","by":{"1":"13, 14","2":"9, 15, 29"},"q":[{"src":"brief","b":1,"text":"if it would give a reasonable investor the ‘impression of a state of affairs that differs in a material way from the one that actually exists.’","cite":"527 F.3d 982, 985"},{"src":"brief","b":2,"text":"[r]isk disclosures that ‘speak entirely of as-yet-unrealized risks and contingencies’ and do not ‘alert the reader that some of these risks may already have come to fruition’ can mislead reasonable investors.","cite":"527 F.3d 982, 986"},{"src":"brief","b":2,"text":"the risks of product liability claims in the abstract, with no indication that the risk ‘may already have come to fruition.’","cite":"527 F.3d 982, 986"},{"src":"argument","who":"Mr. Barber","text":"I don't think that that's a major concern for us just because this has been the law, for example, in the Ninth Circuit since at least 2008 with the Berson case."}]},{"t":"case","label":"City of Sarasota Firefighters’ Pension Fund v. Inovalon Holdings, Inc.","cite":"319 A.3d 271","y":2024,"court":"Del.","url":"https://www.courtlistener.com/c/A.3d/319/271/","by":{"1":"14"}},{"t":"case","label":"Dolphin & Bradbury, Inc. v. SEC","cite":"512 F.3d 634","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/512/634/","by":{"1":"40","2":"17"}},{"t":"case","label":"FindWhat Inv. Grp. v. FindWhat.com","cite":"658 F.3d 1282","y":2011,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/658/1282/","by":{"1":"14","3":"8"}},{"t":"case","label":"Ganino v. Citizens Utils. Co.","cite":"228 F.3d 154","y":2000,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/228/154/","by":{"1":"50"}},{"t":"case","label":"Glazer Capital Mgmt., L.P. v. Forescout Techs., Inc.","cite":"63 F.4th 747","y":2023,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/63/747/","by":{"1":"14","3":"8"}},{"t":"case","label":"Goldman Sachs Grp., Inc. v. Ark. Tchr. Ret. Sys.","cite":"594 U.S. 113","y":2021,"url":"https://supreme.justia.com/cases/federal/us/594/113/","sc":1,"by":{"1":"18"}},{"t":"case","label":"Huddleston v. Herman & MacLean","cite":"640 F.2d 534","y":1981,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/640/534/","by":{"1":"14, 15"},"q":[{"src":"brief","b":1,"text":"To warn that the untoward may occur when the event is contingent is prudent; to caution that it is only possible for the unfavorable events to happen when they have already occurred is deceit.","cite":"640 F.2d at 544"}]},{"t":"case","label":"Junius Constr. Co. v. Cohen","cite":"178 N.E. 672","y":1931,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E./178/672/","by":{"1":"21"}},{"t":"case","label":"Kisor v. Wilkie","cite":"588 U.S. 558","y":2019,"id":"2018/18-15","sc":1,"by":{"1":"33"}},{"t":"case","label":"Kohl v. Loma Negra Compañía Indus. Argentina Sociedad Anónima","cite":"195 A.D.3d 414","y":2021,"court":"N.Y. App. Div.","url":"https://www.courtlistener.com/c/A.D.3d/195/414/","by":{"1":"14"}},{"t":"case","label":"Lormand v. US Unwired, Inc.","cite":"565 F.3d 228","y":2009,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/565/228/","by":{"1":"14"}},{"t":"case","label":"Meyer v. Jinkosolar Holdings Co., Ltd.","cite":"761 F.3d 245","y":2014,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/761/245/","by":{"1":"14"}},{"t":"case","label":"Paskowitz v. Arnall","cite":"2019 WL 3841999","y":2019,"court":"W.D.N.C.","by":{"1":"14"}},{"t":"case","label":"Provenz v. Miller","cite":"102 F.3d 1478","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/102/1478/","by":{"1":"48","2":"33"},"q":[{"src":"brief","b":1,"text":"transmitted to the public with a degree of intensity and credibility sufficient to effectively counterbalance any misleading impression.","cite":"102 F.3d 1478, 1493"}]},{"t":"case","label":"Rubinstein v. Collins","cite":"20 F.3d 160","y":1994,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/20/160/","by":{"1":"14","2":"14, 16","3":"8"},"q":[{"src":"brief","b":2,"text":"To warn that the untoward may occur when the event is contingent is prudent; to caution that it is only possible for the unfavorable events to happen when they have already occurred is deceit.","cite":"20 F.3d 160, 171"}]},{"t":"case","label":"SEC v. Terry’s Tips, Inc.","cite":"409 F. Supp. 2d 526","y":2006,"court":"D. Vt.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/409/526/","by":{"1":"14"}},{"t":"case","label":"Slack Techs., LLC v. Pirani","cite":"598 U.S. 759","y":2023,"id":"2022/22-200","sc":1,"by":{"1":"38"}},{"t":"case","label":"Slayton v. Am. Exp. Co.","cite":"604 F.3d 758","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/604/758/","by":{"1":"14, 38"}},{"t":"case","label":"Toussaint v. Care.com Inc.","cite":"490 F. Supp. 3d 341","y":2020,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/490/341/","by":{"1":"42"}},{"t":"case","label":"Universal Health Servs., Inc. v. United States ex rel. Escobar","cite":"579 U.S. 176","y":2016,"id":"2015/15-7","sc":1,"by":{"1":"13, 14, 21","2":"13"},"q":[{"src":"brief","b":1,"text":"state[s] the truth only so far as it goes, while omitting critical qualifying information.","cite":"579 U.S. 176, 188"},{"src":"brief","b":1,"text":"that a third potential road might bisect the property.","cite":"579 U.S. 176, 188-89"}]},{"t":"case","label":"Virginia Bankshares, Inc. v. Sandberg","cite":"501 U.S. 1083","y":1991,"id":"1990/89-1448","sc":1,"by":{"1":"35"},"q":[{"src":"brief","b":1,"text":"when placed in a proxy solicitation incorporating statements of fact sufficient to enable readers to draw their own, independent conclusions,","cite":"501 U.S. 1083, 1090"}]},{"t":"case","label":"Williams v. Globus Medical, Inc.","cite":"869 F.3d 235","y":2017,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/869/235/","by":{"1":"14, 42","2":"17"}},{"t":"usc","label":"15 U.S.C. § 78a-78qq","url":"https://www.law.cornell.edu/uscode/text/15/78a-78qq","by":{"1":"6"}},{"t":"usc","label":"15 U.S.C. § 78j","url":"https://www.law.cornell.edu/uscode/text/15/78j","subs":["(b)"],"stext":{"head":"§78j. Manipulative and deceptive devices","paras":[[0,"It shall be unlawful for any person, directly or indirectly, by the use of any means or instrumentality of interstate commerce or of the mails, or of any facility of any national securities exchange—"],[1,"(a)(1) To effect a short sale, or to use or employ any stop-loss order in connection with the purchase or sale, of any security other than a government security, in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(2) Paragraph (1) of this subsection shall not apply to security futures products."],[1,"(b) To use or employ, in connection with the purchase or sale of any security registered on a national securities exchange or any security not so registered, or any securities-based swap agreement 1 any manipulative or deceptive device or contrivance in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(c)(1) To effect, accept, or facilitate a transaction involving the loan or borrowing of securities in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(2) Nothing in paragraph (1) may be construed to limit the authority of the appropriate Federal banking agency (as defined in section 1813(q) of title 12), the National Credit Union Administration, or any other Federal department or agency having a responsibility under Federal law to prescribe rules or regulations restricting transactions involving the loan or borrowing of securities in order to protect the safety and soundness of a financial institution or to protect the financial system from systemic risk."],[0,"Rules promulgated under subsection (b) that prohibit fraud, manipulation, or insider trading (but not rules imposing or specifying reporting or recordkeeping requirements, procedures, or standards as prophylactic measures against fraud, manipulation, or insider trading), and judicial precedents decided under subsection (b) and rules promulgated thereunder that prohibit fraud, manipulation, or insider trading, shall apply to security-based swap agreements to the same extent as they apply to securities. Judicial precedents decided under section 77q(a) of this title and sections 78i, 78o, 78p, 78t, and 78u–1 of this title, and judicial precedents decided under applicable rules promulgated under such sections, shall apply to security-based swap agreements to the same extent as they apply to securities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78j?type=usc&year=mostrecent&link-type=html"},"by":{"1":"6, 36","2":"3","3":"1, 2, 15"},"q":[{"src":"brief","b":2,"text":"[t]o use or employ, in connection with the purchase or sale of any security[,] * * * any manipulative or deceptive device or contrivance in contravention of","cite":"15 U.S.C. 78j(b)"}]},{"t":"usc","label":"15 U.S.C. § 78m","url":"https://www.law.cornell.edu/uscode/text/15/78m","subs":["(a)"],"stext":{"head":"§78m. Periodical and other reports","paras":[[0,"(a) Reports by issuer of security; contents"],[0,"Every issuer of a security registered pursuant to section 78l of this title shall file with the Commission, in accordance with such rules and regulations as the Commission may prescribe as necessary or appropriate for the proper protection of investors and to insure fair dealing in the security—"],[1,"(1) such information and documents (and such copies thereof) as the Commission shall require to keep reasonably current the information and documents required to be included in or filed with an application or registration statement filed pursuant to section 78l of this title, except that the Commission may not require the filing of any material contract wholly executed before July 1, 1962."],[1,"(2) such annual reports (and such copies thereof), certified if required by the rules and regulations of the Commission by independent public accountants, and such quarterly reports (and such copies thereof), as the Commission may prescribe."],[0,"Every issuer of a security registered on a national securities exchange shall also file a duplicate original of such information, documents, and reports with the exchange. In any registration statement, periodic report, or other reports to be filed with the Commission, an emerging growth company need not present selected financial data in accordance with section 229.301 of title 17, Code of Federal Regulations, for any period prior to the earliest audited period presented in connection with its first registration statement that became effective under this chapter or the Securities Act of 1933 [15 U.S.C. 77a et seq.] and, with respect to any such statement or reports, an emerging growth company may not be required to comply with any new or revised financial accounting standard until such date that a company that is not an issuer (as defined under section 7201 of this title) is required to comply with such new or revised accounting standard, if such standard applies to companies that are not issuers."],[0,"(b) Form of report; books, records, and internal accounting; directives"],[0,"(1) The Commission may prescribe, in regard to reports made pursuant to this chapter, the form or forms in which the required information shall be set forth, the items or details to be shown in the balance sheet and the earnings statement, and the methods to be followed in the preparation of reports, in the appraisal or valuation of assets and liabilities, in the determination of depreciation and depletion, in the differentiation of recurring and nonrecurring income, in the differentiation of investment and operating income, and in the preparation, where the Commission deems it necessary or desirable, of separate and/or consolidated balance sheets or income accounts of any person directly or indirectly controlling or controlled by the issuer, or any person under direct or indirect common control with the issuer; but in the case of the reports of any person whose methods of accounting are prescribed under the provisions of any law of the United States, or any rule or regulation thereunder, the rules and regulations of the Commission with respect to reports shall not be inconsistent with the requirements imposed by such law or rule or regulation in respect of the same subject matter (except that such rules and regulations of the Commission may be inconsistent with such requirements to the extent that the Commission determines that the public interest or the protection of investors so requires)."],[0,"(2) Every issuer which has a class of securities registered pursuant to section 78l of this title and every issuer which is required to file reports pursuant to section 78o(d) of this title shall—"],[1,"(A) make and keep books, records, and accounts, which, in reasonable detail, accurately and fairly reflect the transactions and dispositions of the assets of the issuer;"],[1,"(B) devise and maintain a system of internal accounting controls sufficient to provide reasonable assurances that—"],[2,"(i) transactions are executed in accordance with management's general or specific authorization;"],[2,"(ii) transactions are recorded as necessary (I) to permit preparation of financial statements in conformity with generally accepted accounting principles or any other criteria applicable to such statements, and (II) to maintain accountability for assets;"],[2,"(iii) access to assets is permitted only in accordance with management's general or specific authorization; and"],[2,"(iv) the recorded accountability for assets is compared with the existing assets at reasonable intervals and appropriate action is taken with respect to any differences; and"],[1,"(C) notwithstanding any other provision of law, pay the allocable share of such issuer of a reasonable annual accounting support fee or fees, determined in accordance with section 7219 of this title."],[0,"(3)(A) With respect to matters concerning the national security of the United States, no duty or liability under paragraph (2) of this subsection shall be imposed upon any person acting in cooperation with the head of any Federal department or agency responsible for such matters if such act in cooperation with such head of a department or agency was done upon the specific, written directive of the head of such department or agency pursuant to Presidential authority to issue such directives. Each directive issued under this paragraph shall set forth the specific facts and circumstances with respect to which the provisions of this paragraph are to be invoked. Each such directive shall, unless renewed in writing, expire one year after the date of issuance."],[0,"(B) Each head of a Federal department or agency of the United States who issues a directive pursuant to this paragraph shall maintain a complete file of all such directives and shall, on October 1 of each year, transmit a summary of matters covered by such directives in force at any time during the previous year to the Permanent Select Committee on Intelligence of the House of Representatives and the Select Committee on Intelligence of the Senate."],[0,"(4) No criminal liability shall be imposed for failing to comply with the requirements of paragraph (2) of this subsection except as provided in paragraph (5) of this subsection."],[0,"(5) No person shall knowingly circumvent or knowingly fail to implement a system of internal accounting controls or knowingly falsify any book, record, or account described in paragraph (2)."],[0,"(6) Where an issuer which has a class of securities registered pursuant to section 78l of this title or an issuer which is required to file reports pursuant to section 78o(d) of this title holds 50 per centum or less of the voting power with respect to a domestic or foreign firm, the provisions of paragraph (2) require only that the issuer proceed in good faith to use its influence, to the extent reasonable under the issuer's circumstances, to cause such domestic or foreign firm to devise and maintain a system of internal accounting controls consistent with paragraph (2). Such circumstances include the relative degree of the issuer's ownership of the domestic or foreign firm and the laws and practices governing the business operations of the country in which such firm is located. An issuer which demonstrates good faith efforts to use such influence shall be conclusively presumed to have complied with the requirements of paragraph (2)."],[0,"(7) For the purpose of paragraph (2) of this subsection, the terms \"reasonable assurances\" and \"reasonable detail\" mean such level of detail and degree of assurance as would satisfy prudent officials in the conduct of their own affairs."],[0,"(c) Alternative reports"],[0,"If in the judgment of the Commission any report required under subsection (a) is inapplicable to any specified class or classes of issuers, the Commission shall require in lieu thereof the submission of such reports of comparable character as it may deem applicable to such class or classes of issuers."],[0,"(d) Reports by persons acquiring more than five per centum of certain classes of securities"],[0,"(1) Any person who, after acquiring directly or indirectly the beneficial ownership of any equity security of a class which is registered pursuant to section 78l of this title, or any equity security of an insurance company which would have been required to be so registered except for the exemption contained in section 78l(g)(2)(G) of this title, or any equity security issued by a closed-end investment company registered under the Investment Company Act of 1940 [15 U.S.C. 80a–1 et seq.] or any equity security issued by a Native Corporation pursuant to section 1629c(d)(6) of title 43, or otherwise becomes or is deemed to become a beneficial owner of any of the foregoing upon the purchase or sale of a security-based swap that the Commission may define by rule, and is directly or indirectly the beneficial owner of more than 5 per centum of such class shall, within ten days after such acquisition or within such shorter time as the Commission may establish by rule, file with the Commission, a statement containing such of the following information, and such additional information, as the Commission may by rules and regulations, prescribe as necessary or appropriate in the public interest or for the protection of investors—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78m?type=usc&year=mostrecent&link-type=html"},"by":{"1":"40","2":"2"}},{"t":"usc","label":"15 U.S.C. § 78t","url":"https://www.law.cornell.edu/uscode/text/15/78t","subs":["(a)"],"by":{"1":"6"}},{"t":"usc","label":"15 U.S.C. § 78t-1","url":"https://www.law.cornell.edu/uscode/text/15/78t-1","by":{"1":"6"}},{"t":"usc","label":"15 U.S.C. § 78u-5","url":"https://www.law.cornell.edu/uscode/text/15/78u-5","subs":["(b)","(c)(1)(A)(i)","(g)","(i)"],"stext":{"head":"§78u–5. Application of safe harbor for forward-looking statements","paras":[[0,"(a) Applicability"],[0,"This section shall apply only to a forward-looking statement made by—"],[1,"(1) an issuer that, at the time that the statement is made, is subject to the reporting requirements of section 78m(a) of this title or section 78o(d) of this title;"],[1,"(2) a person acting on behalf of such issuer;"],[1,"(3) an outside reviewer retained by such issuer making a statement on behalf of such issuer; or"],[1,"(4) an underwriter, with respect to information provided by such issuer or information derived from information provided by such issuer."],[0,"(b) Exclusions"],[0,"Except to the extent otherwise specifically provided by rule, regulation, or order of the Commission, this section shall not apply to a forward-looking statement—"],[1,"(1) that is made with respect to the business or operations of the issuer, if the issuer—"],[2,"(A) during the 3-year period preceding the date on which the statement was first made—"],[3,"(i) was convicted of any felony or misdemeanor described in clauses (i) through (iv) of section 78o(b)(4)(B) of this title; or"],[3,"(ii) has been made the subject of a judicial or administrative decree or order arising out of a governmental action that—"],[4,"(I) prohibits future violations of the antifraud provisions of the securities laws;"],[4,"(II) requires that the issuer cease and desist from violating the antifraud provisions of the securities laws; or"],[4,"(III) determines that the issuer violated the antifraud provisions of the securities laws;"],[2,"(B) makes the forward-looking statement in connection with an offering of securities by a blank check company;"],[2,"(C) issues penny stock;"],[2,"(D) makes the forward-looking statement in connection with a rollup transaction; or"],[2,"(E) makes the forward-looking statement in connection with a going private transaction; or"],[1,"(2) that is—"],[2,"(A) included in a financial statement prepared in accordance with generally accepted accounting principles;"],[2,"(B) contained in a registration statement of, or otherwise issued by, an investment company;"],[2,"(C) made in connection with a tender offer;"],[2,"(D) made in connection with an initial public offering;"],[2,"(E) made in connection with an offering by, or relating to the operations of, a partnership, limited liability company, or a direct participation investment program; or"],[2,"(F) made in a disclosure of beneficial ownership in a report required to be filed with the Commission pursuant to section 78m(d) of this title."],[0,"(c) Safe harbor"],[0,"(1) In general"],[1,"Except as provided in subsection (b), in any private action arising under this chapter that is based on an untrue statement of a material fact or omission of a material fact necessary to make the statement not misleading, a person referred to in subsection (a) shall not be liable with respect to any forward-looking statement, whether written or oral, if and to the extent that—"],[2,"(A) the forward-looking statement is—"],[3,"(i) identified as a forward-looking statement, and is accompanied by meaningful cautionary statements identifying important factors that could cause actual results to differ materially from those in the forward-looking statement; or"],[3,"(ii) immaterial; or"],[2,"(B) the plaintiff fails to prove that the forward-looking statement—"],[3,"(i) if made by a natural person, was made with actual knowledge by that person that the statement was false or misleading; or"],[3,"(ii) if made by a business entity; 1 was—"],[4,"(I) made by or with the approval of an executive officer of that entity; and"],[4,"(II) made or approved by such officer with actual knowledge by that officer that the statement was false or misleading."],[0,"(2) Oral forward-looking statements"],[1,"In the case of an oral forward-looking statement made by an issuer that is subject to the reporting requirements of section 78m(a) of this title or section 78o(d) of this title, or by a person acting on behalf of such issuer, the requirement set forth in paragraph (1)(A) shall be deemed to be satisfied—"],[2,"(A) if the oral forward-looking statement is accompanied by a cautionary statement—"],[3,"(i) that the particular oral statement is a forward-looking statement; and"],[3,"(ii) that the actual results might differ materially from those projected in the forward-looking statement; and"],[2,"(B) if—"],[3,"(i) the oral forward-looking statement is accompanied by an oral statement that additional information concerning factors that could cause actual results to materially differ from those in the forward-looking statement is contained in a readily available written document, or portion thereof;"],[3,"(ii) the accompanying oral statement referred to in clause (i) identifies the document, or portion thereof, that contains the additional information about those factors relating to the forward-looking statement; and"],[3,"(iii) the information contained in that written document is a cautionary statement that satisfies the standard established in paragraph (1)(A)."],[0,"(3) Availability"],[1,"Any document filed with the Commission or generally disseminated shall be deemed to be readily available for purposes of paragraph (2)."],[0,"(4) Effect on other safe harbors"],[1,"The exemption provided for in paragraph (1) shall be in addition to any exemption that the Commission may establish by rule or regulation under subsection (g)."],[0,"(d) Duty to update"],[0,"Nothing in this section shall impose upon any person a duty to update a forward-looking statement."],[0,"(e) Dispositive motion"],[0,"On any motion to dismiss based upon subsection (c)(1), the court shall consider any statement cited in the complaint and any cautionary statement accompanying the forward-looking statement, which are not subject to material dispute, cited by the defendant."],[0,"(f) Stay pending decision on motion"],[0,"In any private action arising under this chapter, the court shall stay discovery (other than discovery that is specifically directed to the applicability of the exemption provided for in this section) during the pendency of any motion by a defendant for summary judgment that is based on the grounds that—"],[1,"(1) the statement or omission upon which the complaint is based is a forward-looking statement within the meaning of this section; and"],[1,"(2) the exemption provided for in this section precludes a claim for relief."],[0,"(g) Exemption authority"],[0,"In addition to the exemptions provided for in this section, the Commission may, by rule or regulation, provide exemptions from or under any provision of this chapter, including with respect to liability that is based on a statement or that is based on projections or other forward-looking information, if and to the extent that any such exemption is consistent with the public interest and the protection of investors, as determined by the Commission."],[0,"(h) Effect on other authority of Commission"],[0,"Nothing in this section limits, either expressly or by implication, the authority of the Commission to exercise similar authority or to adopt similar rules and regulations with respect to forward-looking statements under any other statute under which the Commission exercises rulemaking authority."],[0,"(i) Definitions"],[0,"For purposes of this section, the following definitions shall apply:"],[0,"(1) Forward-looking statement"],[1,"The term \"forward-looking statement\" means—"],[2,"(A) a statement containing a projection of revenues, income (including income loss), earnings (including earnings loss) per share, capital expenditures, dividends, capital structure, or other financial items;"],[2,"(B) a statement of the plans and objectives of management for future operations, including plans or objectives relating to the products or services of the issuer;"],[2,"(C) a statement of future economic performance, including any such statement contained in a discussion and analysis of financial condition by the management or in the results of operations included pursuant to the rules and regulations of the Commission;"],[2,"(D) any statement of the assumptions underlying or relating to any statement described in subparagraph (A), (B), or (C);"],[2,"(E) any report issued by an outside reviewer retained by an issuer, to the extent that the report assesses a forward-looking statement made by the issuer; or"],[2,"(F) a statement containing a projection or estimate of such other items as may be specified by rule or regulation of the Commission."],[0,"(2) Investment company"],[1,"The term \"investment company\" has the same meaning as in section 80a–3(a) of this title."],[0,"(3) Going private transaction"],[1,"The term \"going private transaction\" has the meaning given that term under the rules or regulations of the Commission issued pursuant to section 78m(e) of this title."],[0,"(4) Person acting on behalf of an issuer"],[1,"The term \"person acting on behalf of an issuer\" means any officer, director, or employee of such issuer."],[0,"(5) Other terms"],[1,"The terms \"blank check company\", \"rollup transaction\", \"partnership\", \"limited liability company\", \"executive officer of an entity\" and \"direct participation investment program\", have the meanings given those terms by rule or regulation of the Commission."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78u-5?type=usc&year=mostrecent&link-type=html"},"by":{"1":"37, 37, 37, 37","2":"24, 25"},"q":[{"src":"brief","b":2,"text":"accompanied by meaning- ful cautionary statements.","cite":"15 U.S.C. 78u-5(c)(1)(A)(i)"}]},{"t":"reg","label":"17 C.F.R. § 229.101","url":"https://www.ecfr.gov/current/title-17/section-229.101","by":{"1":"30"}},{"t":"reg","label":"17 C.F.R. § 229.103","url":"https://www.ecfr.gov/current/title-17/section-229.103","by":{"1":"31"}},{"t":"reg","label":"17 C.F.R. § 229.105","url":"https://www.ecfr.gov/current/title-17/section-229.105","subs":["(a)","(b)"],"by":{"1":"25, 26, 27, 29, 30, 33, 36, 37, 39, 40, 42, 43, 10, 27, 39, 27"},"q":[{"src":"brief","b":1,"text":"discussion of the material factors that make an investment in the registrant or offering speculative or risky.","cite":"17 C.F.R. § 229.105(a)"},{"src":"brief","b":1,"text":"factors that make an investment . . . speculative or risky.","cite":"17 C.F.R. § 229.105(a)"}]},{"t":"reg","label":"17 C.F.R. § 229.106","url":"https://www.ecfr.gov/current/title-17/section-229.106","by":{"1":"31"}},{"t":"reg","label":"17 C.F.R. § 229.303","url":"https://www.ecfr.gov/current/title-17/section-229.303","by":{"1":"31, 35, 36"}},{"t":"reg","label":"17 C.F.R. § 229.503","url":"https://www.ecfr.gov/current/title-17/section-229.503","subs":["(c)"],"by":{"1":"29"},"q":[{"src":"brief","b":1,"text":"any factors that make the offering speculative or risky.","cite":"17 C.F.R. § 229.503(c)"}]},{"t":"reg","label":"17 C.F.R. § 240.10b-5","url":"https://www.ecfr.gov/current/title-17/section-240.10b-5","subs":["(b)"],"by":{"1":"13, 15, 47"},"q":[{"src":"brief","b":1,"text":"omit[ting] to state a material fact necessary in order to make the statements made, in the light of the circumstances under which they were made, not misleading.","cite":"17 C.F.R. § 240.10b-5(b)"}]},{"t":"reg","label":"17 C.F.R. § 240.3b-6","url":"https://www.ecfr.gov/current/title-17/section-240.3b-6","subs":["(a)"],"by":{"1":"38"}},{"t":"reg","label":"Commission Statement and Guidance on Public Company Cybersecurity Disclosures, 83 Fed. Reg. 8,166","url":"https://www.govinfo.gov/link/fr/83/8166","by":{"1":"31, 32, 40, 46","2":"18"}},{"t":"reg","label":"FAST Act Modernization and Simplification of Regulation S-K, 84 Fed. Reg. 12,674","url":"https://www.govinfo.gov/link/fr/84/12674","by":{"1":"29, 30"}},{"t":"reg","label":"Guides for Preparation and Filing of Registration Statements, 33 Fed. Reg. 18,617","url":"https://www.govinfo.gov/link/fr/33/18617","by":{"1":"29"}},{"t":"reg","label":"Modernization of Regulation S-K Items 101, 103, and 105, 85 Fed. Reg. 63,726","url":"https://www.govinfo.gov/link/fr/85/63726","by":{"1":"39","2":"26"}},{"t":"reg","label":"Sec. Offering Reform, 70 Fed. Reg. 44,722","url":"https://www.govinfo.gov/link/fr/70/44722","by":{"1":"29","2":"2"}},{"t":"case","label":"Asher v. Baxter Int’l Inc.","cite":"377 F.3d 727","y":2004,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/377/727/","by":{"2":"25"}},{"t":"case","label":"Chiarella v. United States","cite":"445 U.S. 222","y":1980,"id":"1979/78-1202","sc":1,"by":{"2":"3"},"q":[{"src":"brief","b":2,"text":"Section 10(b) is aptly described as a catchall","cite":"445 U.S. 222, 234-235"}]},{"t":"case","label":"Cora Pub, Inc. v. Continental Cas. Co.","cite":"619 F.2d 482","y":1980,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/619/482/","by":{"2":"17"}},{"t":"case","label":"Dura Pharm., Inc. v. Broudo","cite":"544 U.S. 336","y":2005,"id":"2004/03-932","sc":1,"by":{"2":"4"}},{"t":"case","label":"Field v. Mans","cite":"157 F.3d 35","y":1998,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/157/35/","by":{"2":"17"}},{"t":"case","label":"SEC v. Fundpack, Inc.","cite":"1979 WL 1238","y":1979,"court":"D.D.C. Aug. 16","by":{"2":"19"}},{"t":"case","label":"SEC v. Tecumseh Holdings Corp.","cite":"765 F. Supp. 2d 340","y":2011,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/765/340/","by":{"2":"18","3":"12"}},{"t":"case","label":"SEC v. True N. Fin. Corp.","cite":"909 F. Supp. 2d 1073","y":2012,"court":"D. Minn.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/909/1073/","by":{"2":"18","3":"12"}},{"t":"case","label":"SEC v. Zandford","cite":"535 U.S. 813","y":2002,"id":"2001/01-147","sc":1,"by":{"2":"3"},"q":[{"src":"brief","b":2,"text":"Rule 10b-5 is coextensive with the coverage of § 10(b).","cite":"535 U.S. 813, 816 n.1"}]},{"t":"case","label":"Siracusano v. Matrixx Initiatives, Inc.","cite":"585 F.3d 1167","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/585/1167/","by":{"2":"15, 28","3":"8"}},{"t":"case","label":"Stoneridge Inv. Partners, LLC v. Scientific-Atlanta, Inc.","cite":"552 U.S. 148","y":2008,"id":"2007/06-43","sc":1,"by":{"2":"4","3":"17"},"q":[{"src":"brief","b":3,"text":"[c]oncerns with the judicial creation of a private cause of action caution against its expansion.","cite":"552 U.S. 148, 163, 165"},{"src":"brief","b":3,"text":"provide a further reason to reject","cite":"552 U.S. at 163"}]},{"t":"usc","label":"15 U.S.C. § 77a","url":"https://www.law.cornell.edu/uscode/text/15/77a","by":{"2":"2"}},{"t":"usc","label":"15 U.S.C. § 77d","url":"https://www.law.cornell.edu/uscode/text/15/77d","by":{"2":"2"}},{"t":"usc","label":"15 U.S.C. § 77e","url":"https://www.law.cornell.edu/uscode/text/15/77e","by":{"2":"2"}},{"t":"usc","label":"15 U.S.C. § 77k","url":"https://www.law.cornell.edu/uscode/text/15/77k","subs":["(a)"],"stext":{"head":"§77k. Civil liabilities on account of false registration statement","paras":[[0,"(a) Persons possessing cause of action; persons liable"],[0,"In case any part of the registration statement, when such part became effective, contained an untrue statement of a material fact or omitted to state a material fact required to be stated therein or necessary to make the statements therein not misleading, any person acquiring such security (unless it is proved that at the time of such acquisition he knew of such untruth or omission) may, either at law or in equity, in any court of competent jurisdiction, sue—"],[1,"(1) every person who signed the registration statement;"],[1,"(2) every person who was a director of (or person performing similar functions) or partner in the issuer at the time of the filing of the part of the registration statement with respect to which his liability is asserted;"],[1,"(3) every person who, with his consent, is named in the registration statement as being or about to become a director, person performing similar functions, or partner;"],[1,"(4) every accountant, engineer, or appraiser, or any person whose profession gives authority to a statement made by him, who has with his consent been named as having prepared or certified any part of the registration statement, or as having prepared or certified any report or valuation which is used in connection with the registration statement, with respect to the statement in such registration statement, report, or valuation, which purports to have been prepared or certified by him;"],[1,"(5) every underwriter with respect to such security."],[0,"If such person acquired the security after the issuer has made generally available to its security holders an earning statement covering a period of at least twelve months beginning after the effective date of the registration statement, then the right of recovery under this subsection shall be conditioned on proof that such person acquired the security relying upon such untrue statement in the registration statement or relying upon the registration statement and not knowing of such omission, but such reliance may be established without proof of the reading of the registration statement by such person."],[0,"(b) Persons exempt from liability upon proof of issues"],[0,"Notwithstanding the provisions of subsection (a) no person, other than the issuer, shall be liable as provided therein who shall sustain the burden of proof—"],[1,"(1) that before the effective date of the part of the registration statement with respect to which his liability is asserted (A) he had resigned from or had taken such steps as are permitted by law to resign from, or ceased or refused to act in, every office, capacity, or relationship in which he was described in the registration statement as acting or agreeing to act, and (B) he had advised the Commission and the issuer in writing that he had taken such action and that he would not be responsible for such part of the registration statement; or"],[1,"(2) that if such part of the registration statement became effective without his knowledge, upon becoming aware of such fact he forthwith acted and advised the Commission, in accordance with paragraph (1) of this subsection, and, in addition, gave reasonable public notice that such part of the registration statement had become effective without his knowledge; or"],[1,"(3) that (A) as regards any part of the registration statement not purporting to be made on the authority of an expert, and not purporting to be a copy of or extract from a report or valuation of an expert, and not purporting to be made on the authority of a public official document or statement, he had, after reasonable investigation, reasonable ground to believe and did believe, at the time such part of the registration statement became effective, that the statements therein were true and that there was no omission to state a material fact required to be stated therein or necessary to make the statements therein not misleading; and (B) as regards any part of the registration statement purporting to be made upon his authority as an expert or purporting to be a copy of or extract from a report or valuation of himself as an expert, (i) he had, after reasonable investigation, reasonable ground to believe and did believe, at the time such part of the registration statement became effective, that the statements therein were true and that there was no omission to state a material fact required to be stated therein or necessary to make the statements therein not misleading, or (ii) such part of the registration statement did not fairly represent his statement as an expert or was not a fair copy of or extract from his report or valuation as an expert; and (C) as regards any part of the registration statement purporting to be made on the authority of an expert (other than himself) or purporting to be a copy of or extract from a report or valuation of an expert (other than himself), he had no reasonable ground to believe and did not believe, at the time such part of the registration statement became effective, that the statements therein were untrue or that there was an omission to state a material fact required to be stated therein or necessary to make the statements therein not misleading, or that such part of the registration statement did not fairly represent the statement of the expert or was not a fair copy of or extract from the report or valuation of the expert; and (D) as regards any part of the registration statement purporting to be a statement made by an official person or purporting to be a copy of or extract from a public official document, he had no reasonable ground to believe and did not believe, at the time such part of the registration statement became effective, that the statements therein were untrue, or that there was an omission to state a material fact required to be stated therein or necessary to make the statements therein not misleading, or that such part of the registration statement did not fairly represent the statement made by the official person or was not a fair copy of or extract from the public official document."],[0,"(c) Standard of reasonableness"],[0,"In determining, for the purpose of paragraph (3) of subsection (b) of this section, what constitutes reasonable investigation and reasonable ground for belief, the standard of reasonableness shall be that required of a prudent man in the management of his own property."],[0,"(d) Effective date of registration statement with regard to underwriters"],[0,"If any person becomes an underwriter with respect to the security after the part of the registration statement with respect to which his liability is asserted has become effective, then for the purposes of paragraph (3) of subsection (b) of this section such part of the registration statement shall be considered as having become effective with respect to such person as of the time when he became an underwriter."],[0,"(e) Measure of damages; undertaking for payment of costs"],[0,"The suit authorized under subsection (a) may be to recover such damages as shall represent the difference between the amount paid for the security (not exceeding the price at which the security was offered to the public) and (1) the value thereof as of the time such suit was brought, or (2) the price at which such security shall have been disposed of in the market before suit, or (3) the price at which such security shall have been disposed of after suit but before judgment if such damages shall be less than the damages representing the difference between the amount paid for the security (not exceeding the price at which the security was offered to the public) and the value thereof as of the time such suit was brought: Provided, That if the defendant proves that any portion or all of such damages represents other than the depreciation in value of such security resulting from such part of the registration statement, with respect to which his liability is asserted, not being true or omitting to state a material fact required to be stated therein or necessary to make the statements therein not misleading, such portion of or all such damages shall not be recoverable. In no event shall any underwriter (unless such underwriter shall have knowingly received from the issuer for acting as an underwriter some benefit, directly or indirectly, in which all other underwriters similarly situated did not share in proportion to their respective interests in the underwriting) be liable in any suit or as a consequence of suits authorized under subsection (a) for damages in excess of the total price at which the securities underwritten by him and distributed to the public were offered to the public. In any suit under this or any other section of this subchapter the court may, in its discretion, require an undertaking for the payment of the costs of such suit, including reasonable attorney's fees, and if judgment shall be rendered against a party litigant, upon the motion of the other party litigant, such costs may be assessed in favor of such party litigant (whether or not such undertaking has been required) if the court believes the suit or the defense to have been without merit, in an amount sufficient to reimburse him for the reasonable expenses incurred by him, in connection with such suit, such costs to be taxed in the manner usually provided for taxing of costs in the court in which the suit was heard."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77k?type=usc&year=mostrecent&link-type=html"},"by":{"2":"21"},"q":[{"src":"brief","b":2,"text":"contain[] an untrue statement of a material fact or omit[] to state a material fact * * * necessary to make the statements therein not misleading.","cite":"15 U.S.C. 77k(a)"}]},{"t":"usc","label":"15 U.S.C. § 78l","url":"https://www.law.cornell.edu/uscode/text/15/78l","by":{"2":"2"}},{"t":"reg","label":"29 Fed. Reg. 2490","url":"https://www.govinfo.gov/link/fr/29/2490","by":{"2":"2, 18"}},{"t":"reg","label":"47 Fed. Reg. 11,380","url":"https://www.govinfo.gov/link/fr/47/11380","by":{"2":"2"}},{"t":"case","label":"EP Medsystems, Inc. v. EchoCath, Inc.","cite":"235 F.3d 865","y":2000,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/235/865/","by":{"3":"16"}},{"t":"case","label":"Keene Corp. v. United States","cite":"508 U.S. 200","y":1993,"id":"1992/92-166","sc":1,"by":{"3":"10"}},{"t":"case","label":"SEC v. Levin","cite":"849 F.3d 995","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/849/995/","by":{"3":"10"},"q":[{"src":"brief","b":3,"text":"includes particular language in one section of a [regulation] but omits it in another, it is generally presumed that [it] acts intentionally and purposely in the disparate inclusion or exclusion.","cite":"849 F.3d 995, 1003-1004"}]},{"t":"case","label":"SEC v. SolarWinds Corp.","cite":"2024 WL 3461952","y":2024,"court":"S.D.N.Y. July 18","by":{"3":"12"},"q":[{"src":"brief","b":3,"text":"did not have a duty to disclose the fact of individual cyber intrusions or attacks.","cite":"2024 WL 3461952"}]},{"t":"case","label":"SEC v. Texas Gulf Sulphur Co.","cite":"401 F.2d 833","y":1968,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/401/833/","by":{"3":"13"},"q":[{"src":"brief","b":3,"text":"into the meaning of the statement to the reasonable investor and its relationship to truth.","cite":"401 F.2d 833, 862"}]},{"t":"case","label":"TSC Industries v. Northway","cite":"426 U.S. 438","y":1976,"id":"1975/74-1471","sc":1,"by":{"3":"14"},"q":[{"src":"brief","b":3,"text":"there is a substantial likelihood that, under all the circumstances, the omitted fact would have assumed actual significance in the deliberations of the rea- sonable shareholder.","cite":"426 U.S. 438, 449"}]},{"t":"reg","label":"83 Fed. Reg. 8,170","url":"https://www.govinfo.gov/link/fr/83/8170","by":{"3":"11"}}]};